"""Create an auditable common 5 FPS IDSSE NPZ from tracking/metadata/event XML.

  * Player slots come from metadata team/player IDs, not a second CSV.
  * Original Sportec frame_id and period are preserved; joins are exact.
  * Event-based `gt_mid` is generated by the original sub_13 heuristic.
  * Ball is never synthesized here.

The original source uses Kloppy coordinates='metrica' multiplied by 105x68,
with the ball from the original Sportec BALL frames in centre-origin metres.
"""
from __future__ import annotations
from pathlib import Path
import re
import numpy as np
import pandas as pd
from settings import MATCHES, MAX_SLOTS, DATA, OUT, PITCH_X, PITCH_Y
from preprocessing import event_rules

PREFIX = {
    'tracking': 'DFL_04_03_positions_raw_observed_',
    'metadata': 'DFL_02_01_matchinformation_',
    'events': 'DFL_03_02_events_raw_',
}


def find_file(root: Path, match: str, kind: str) -> Path:
    """Support both flat Hugging Face downloads and nested Sportec folders."""
    root = Path(root)
    paths = [x for x in root.rglob(f'{PREFIX[kind]}*DFL-MAT-{match}.xml')
             if '.cache' not in x.parts and not any(p.startswith('.') for p in x.parts)]
    if len(paths) != 1:
        raise FileNotFoundError(f'Expected exactly one {kind} XML for {match} beneath {root}, found {len(paths)}: {paths[:4]}')
    return paths[0]


def required_paths(root: Path, match: str) -> dict[str, Path]:
    return {kind: find_file(root,match,kind) for kind in PREFIX}


def download_missing(root: Path, match_ids=MATCHES):
    """Explicit opt-in; can download ~2.6GB. Do not commit originals to git."""
    from huggingface_hub import HfApi, hf_hub_download
    repo = 'pysport/idsse-data'
    files = HfApi().list_repo_files(repo_id=repo, repo_type='dataset')
    root.mkdir(parents=True,exist_ok=True)
    for match in match_ids:
        for kind, prefix in PREFIX.items():
            candidates = [p for p in files if Path(p).name.startswith(prefix) and f'DFL-MAT-{match}.xml' in p]
            if len(candidates) != 1:
                raise RuntimeError(f'Hugging Face: ambiguous {match}/{kind} candidates: {candidates}')
            try:
                find_file(root, match, kind)
            except FileNotFoundError:
                print(f'[download] {match}/{kind}', flush=True)
                hf_hub_download(repo_id=repo,repo_type='dataset', filename=candidates[0],local_dir=str(root))


def _player_array_from_kloppy(raw: Path, meta: Path, match: str):
    from kloppy import sportec
    ds = sportec.load_tracking(raw_data=str(raw), meta_data=str(meta),
                              sample_rate=0.2, coordinates='metrica', only_alive=False)
    df = ds.to_df()
    req = {'period_id','frame_id'}
    if not req.issubset(df.columns):
        raise KeyError(f'{match}: kloppy missing required columns {req-set(df.columns)}')
    home, away = ds.metadata.teams[:2]
    side = [(str(p.player_id), -1) for p in home.players] + [(str(p.player_id), 1) for p in away.players]
    active = [(pid, tm) for pid,tm in side if pid+'_x' in df.columns and pid+'_y' in df.columns and
              df[[pid+'_x',pid+'_y']].notna().any(axis=None)]
    if not active:
        raise ValueError(f'{match}: no player position columns found')
    if len(active)>MAX_SLOTS:
        raise ValueError(f'{match}: {len(active)} players exceed MAX_SLOTS={MAX_SLOTS}; cannot silently trim')
    df = df.sort_values(['period_id','frame_id'],kind='stable').reset_index(drop=True)
    if df.duplicated(['period_id','frame_id']).any():
        raise ValueError(f'{match}: duplicate frame IDs from Kloppy')
    xy = np.full((len(df),MAX_SLOTS,2),np.nan,np.float32)
    teams = np.zeros(MAX_SLOTS,np.int8)
    for j,(pid,team) in enumerate(active):
        xy[:,j,0] = pd.to_numeric(df[pid+'_x'],errors='coerce').to_numpy(np.float32)*PITCH_X
        xy[:,j,1] = pd.to_numeric(df[pid+'_y'],errors='coerce').to_numpy(np.float32)*PITCH_Y
        teams[j] = team
    xy[~np.isfinite(xy).all(axis=-1)] = np.nan
    frames = df['frame_id'].to_numpy(np.int64)
    periods = df['period_id'].to_numpy(np.int16)
    for per in (1,2):
        ix = np.where(periods==per)[0]
        if not len(ix): raise ValueError(f'{match}: period {per} missing')
        diff = np.diff(frames[ix])
        if not np.all(diff==5):
            raise ValueError(f'{match} p{per}: non-contiguous 5FPS from Kloppy ({np.unique(diff,return_counts=True)})')
    return xy,teams,frames,periods


def _original_ball_and_labels(tracking: Path, events: Path, match: str):
    """The original event-based relabel code runs on the native 25FPS time axis."""
    ball, halves = event_rules.read_ball(str(tracking))
    if not len(ball): raise ValueError(f'{match}: BALL frames not found in tracking XML')
    ev = event_rules.read_events(str(events),halves)
    fr = ball.frame_id.to_numpy(np.int64)
    per = ball.period.to_numpy(np.int16)
    alive = ball.alive.to_numpy(bool)
    poss = ball.poss.to_numpy(np.int64)
    orig = np.where(alive,poss,0)
    if np.any(alive & ~np.isin(poss,[1,2])):
        raise ValueError(f'{match}: Alive frames with unknown BallPossession. Inspect XML rather than guessing H/A labels.')
    if len(ev):
        i = np.searchsorted(fr,ev.f.to_numpy()).clip(0,len(fr)-1)
        ok = (ev.kind.to_numpy()=='play_ok') & alive[i]
        if not ok.any():
            raise ValueError(f'{match}: no successful passes for event team mapping')
        ct = pd.crosstab(ev.team.to_numpy()[ok],poss[i][ok])
        mapping = {team:int(ct.loc[team].idxmax()) for team in ct.index}
        ev_code = ev.team.map(mapping).fillna(-1).to_numpy().astype(int)
        mid = event_rules.relabel(orig,per,i,ev_code,ev.kind.to_numpy(),event_rules.LEVELS['mid'])
        loose = event_rules.relabel(orig,per,i,ev_code,ev.kind.to_numpy(),event_rules.LEVELS['loose'])
    else:
        raise ValueError(f'{match}: no events parsed. Do not silently fall back to original GT')
    out = pd.DataFrame({'frame':fr,'period':per,'gt_orig':np.where(orig==0,2,orig-1),
                        'gt_mid':np.where(mid==0,2,mid-1),'gt_loose':np.where(loose==0,2,loose-1)})
    # Sportec raw BALL is in centred metres. Extract at the Kloppy frame IDs later.
    # Read raw x/y only at matching 5FPS frames to keep memory manageable.
    from preprocessing.raw_ball import read_ball_positions
    b = read_ball_positions(tracking)
    out = out.merge(b,on=['frame','period'],how='left',validate='one_to_one')
    if out[['ball_x','ball_y']].isna().all(axis=None):
        raise ValueError(f'{match}: no ball coordinates parsed')
    return out


def build_one(root: Path, match: str, out: Path):
    p=required_paths(root,match)
    xy, teams, frames, periods = _player_array_from_kloppy(p['tracking'],p['metadata'],match)
    ball = _original_ball_and_labels(p['tracking'],p['events'],match)
    want = pd.DataFrame({'frame':frames,'period':periods})
    joined = want.merge(ball,on=['frame','period'],how='left',validate='one_to_one',indicator=True,sort=False)
    if (joined['_merge']!='both').any():
        bad=joined.loc[joined['_merge']!='both',['period','frame']].head(6).to_dict('records')
        raise ValueError(f'{match}: player 5FPS and Sportec BALL frame ID mismatch: {bad}')
    if joined[['gt_orig','gt_mid','gt_loose']].isna().any(axis=None):
        raise ValueError(f'{match}: missing GT after frame join')
    # preserve period boundaries and entire player/balldata rows
    for key in ('gt_orig','gt_mid','gt_loose'):
        if not np.isin(joined[key].to_numpy(),[0,1,2]).all():
            raise ValueError(f'{match}: unexpected {key} labels')
    out.parent.mkdir(parents=True,exist_ok=True)
    np.savez_compressed(out,xy=xy,teams=teams,frame=frames,period=periods,
                        ball=joined[['ball_x','ball_y']].to_numpy(np.float32),
                        gt_orig=joined['gt_orig'].to_numpy(np.int8),
                        gt_mid=joined['gt_mid'].to_numpy(np.int8),
                        gt_loose=joined['gt_loose'].to_numpy(np.int8))
    print(f'[prepare] {match}: {len(frames):,} frames, {int((teams!=0).sum())} slots, ball observed {joined[["ball_x","ball_y"]].notna().all(axis=1).mean():.1%}',flush=True)


def prepare(root=DATA,out_dir=OUT/'base',matches=MATCHES):
    for m in matches:
        f=out_dir/f'{m}.npz'
        if f.is_file():
            print(f'[prepare] cached {f.name}',flush=True)
            continue
        build_one(root,m,f)
